103	+ * lines that are its own.
104	+ */
105	+public abstract class DocumentLayout {
106	+
107	+    public final ReservationReceipt issue(Reservation reservation, Room room) {
108	+        IdentificationFields id = reservation.guest().identification().fields();
109	+        Price price = reservation.price();
110	+        return new ReservationReceipt(
