123	+                price.nights(),
124	+                price.subtotal(),
125	+                price.discount(),
126	+                price.total(),
127	+                text(reservation, room));
128	+    }
129	+
130	+    private String text(Reservation reservation, Room room) {
131	+        Price price = reservation.price();
132	+        return headerLine(reservation.id())
133	+                + identityLines(reservation)
134	+                + roomLine(room)
135	+                + stayLine(reservation)
136	+                + priceLines(price)
137	+                + closingLines(price);
138	+    }
139	+
140	+    protected abstract String title();
141	+
142	+    protected abstract String headerLine(long reservationId);
143	+
