449	new file mode 100644
450	index 0000000..9e6fa04
451	--- /dev/null
452	+++ b/src/main/java/hotel/reservations/Identifications.java
453	@@ -0,0 +1,49 @@
454	+package hotel.reservations;
455	+
456	+import java.util.List;
457	+import java.util.Optional;
458	+import java.util.function.Function;
459	+import java.util.stream.Stream;
460	+
461	+/**
462	+ * Every way a guest can be identified. A new way is a new {@link Identification} and one line in {@link #KINDS}.
463	+ */
464	+public final class Identifications {
465	+
466	+    /** Each kind answers with its identification when the fields it owns are given, and with nothing when none is. */
467	+    private static final List<Function<IdentificationFields, Optional<Identification>>> KINDS = List.of(
468	+            CpfIdentification::from, CompanyIdentification::from, PassportIdentification::from);
469	+
470	+    private Identifications() {
471	+    }
472	+
473	+    /** The identification the fields describe: exactly one kind, with all of its fields. */
474	+    public static Identification from(IdentificationFields fields) {
475	+        List<Identification> given = KINDS.stream()
476	+                .map(kind -> kind.apply(fields))
477	+                .flatMap(Optional::stream)
478	+                .toList();
479	+        if (given.size() != 1) {
480	+            throw new HotelException(ErrorCode.INVALID_REQUEST,
481	+                    "identify the guest with exactly one of: guestCpf; companyCnpj and companyName; "
482	+                            + "guestPassport and guestCountry");
483	+        }
484	+        return given.get(0);
485	+    }
486	+
487	+    static boolean whenGiven(String field) {
488	+        return field != null && !field.isBlank();
489	+    }
490	+
491	+    /** Whether any of the fields is given; a kind that has some but not all of its fields is not valid. */
492	+    static Optional<Identification> ifAny(Identification identification, String... ownFields) {
493	+        long given = Stream.of(ownFields).filter(Identifications::whenGiven).count();
494	+        if (given == 0) {
495	+            return Optional.empty();
496	+        }
497	+        if (given < ownFields.length) {
498	+            throw new HotelException(ErrorCode.INVALID_REQUEST, "the identification of the guest is incomplete");
499	+        }
500	+        return Optional.of(identification);
501	+    }
502	+}
